int A = 10, B = 3;
float F = 5.0f;

int Add = A + B;       // 13
int Sub = A - B;       // 7
int Mul = A * B;       // 30

// Integer division truncates result
int Div_I = A / B;     // 3

// Modulus (remainder) only works on integers
int Mod = A % B;       // 1

// Floating point division requires float operand
float Div_F = F / B;   // 1.666...

int Neg = -A;          // Unary negation: -10
